export type NodeStatus='pending'|'triggered'|'broken'|'cancelled'|'resolved';
export interface HistoryNode { contentId:string; status:NodeStatus; actualCause:string[]; carrier:string; evidence:string[]; resolvedYear?:number; triggeredDay?:number; }
export type ControlLevel='名義影響'|'軍事進入'|'初步接收'|'穩定治理'|'完全實控';
export type PolicyId='屯田與水利'|'減徵與賑濟'|'互市與道路'|'軍糧徵調';
export interface Territory { id:string; name:string; control:ControlLevel; owner:string; population:number; grain:number; support:number; policy:PolicyId|null; interests:{gentry:number;farmers:number;merchants:number}; example:boolean; }
export interface Office { id:string; title:string; territoryId:string; holderId:string|null; vacancySince:number|null; appointment?:{personId:string; arrivalDay:number}; }
export interface Candidate { id:string; name:string; origin:string; specialty:string; age:number; status:'available'|'approached'|'refused'|'recruited'|'competing'; faction:string; example:boolean; willingness:number; approachedDay?:number; }
export interface Route { id:string; from:string; to:string; days:number; terrain:string; risk:number; example:boolean; }
export interface HistoricalPerson {id:string;name:string;alive:boolean;location:string;role:string;deathYear?:number;deathCause?:string;source:string;}
export interface Convoy { id:string; routeId:string; owner:string; item:string; quantity:number; from:string; to:string; daysRemaining:number; status:'traveling'|'arrived'|'lost'; }
export interface BattleCoordinate { x:number; y:number; }
export interface WarUnit { id:string; faction:string; commanderId:string; commanderName:string; location:string; strength:number; reserve:number; supply:number; morale:number; fatigue:number; terrain:string; wounded:number; killed:number; routed:number; order:'待命'|'進攻'|'防守'|'撤退'; position?:BattleCoordinate; sightRadius?:number; }
export interface CampaignFront { id:string; name:string; location:string; overallCommanderId:string; overallCommanderName:string; unitIds:string[]; }
export interface CampaignTransfer { id:string; unitId:string; fromFrontId:string; toFrontId:string; arrivalDay:number; }
export interface MultiFrontCampaign { fronts:CampaignFront[]; units:WarUnit[]; transfers:CampaignTransfer[]; }
export interface BattleSceneObject { id:string; label:string; location:string; condition:string; position?:BattleCoordinate; radius?:number; blocksLineOfSight?:boolean; integrity?:number; destroyed?:boolean; }
export interface BattlePotentialChain { id:string; fromObjectId:string; toObjectId:string; triggerCondition:string; possibleEffect:string; affectedUnitIds:string[]; impactForce?:number; maxDistance?:number; affectedRadius?:number; moraleImpact?:number; casualties?:Array<{unitId:string;killed:number;wounded:number;routed:number}>; }
export interface BattleObserverPosition { id:string; side:string; location:string; visibility:string; position?:BattleCoordinate; sightRange?:number; }
export interface BattleSceneManifest { example:boolean; objects:BattleSceneObject[]; potentialChains:BattlePotentialChain[]; observers:BattleObserverPosition[]; settledChainIds?:string[]; }
export interface Battle { id:string; location:string; startedDay:number; rounds:number; status:'active'|'ended'; overallCommander:{id:string;name:string;unitId:null}; units:WarUnit[]; logs:string[]; protagonistPresent:boolean; witnesses:string[]; scene?:BattleSceneManifest; }
export interface TreatyClause { id:string; text:string; sovereign:boolean; territoryId?:string; successorOwner?:string; }
export interface Treaty { id:string; proposer:string; clauses:TreatyClause[]; status:'draft'|'pending-player'|'approved'|'rejected'|'authorized'; authorizationId?:string; }
export interface Phase4Model {
  version:1; contentVersion:string; day:number; year:number; month:number; dayOfMonth:number;
  nodes:HistoryNode[]; causes:string[]; historicalPersons:HistoricalPerson[]; playerLocation:string; medicalSupplies:number; territories:Territory[]; offices:Office[]; candidates:Candidate[]; routes:Route[]; convoys:Convoy[];
  battle:Battle|null; campaign?:MultiFrontCampaign; treaties:Treaty[]; authorizations:Array<{id:string;scope:string;clauses:string[]}>;
  policiesLog:string[]; externalUpdates:string[]; unified:boolean; ending:'continuing'|'pending'|'chosen'|'complete'; chosenEnding?:string;
  eventLedger:Array<{id:string;day:number;year:number;month:number;dayOfMonth:number;type:string;detail:string;source?:string}>;
}
export type Phase4Action =
 | {type:'AdvanceDays';days:number}
 | {type:'InterveneDeath';nodeId:string;personId:string;method:'一般醫療';location:string}
 | {type:'Appoint';officeId:string;personId:string}
