 const offices:Office[]=[{id:'office-clerk',title:'郡府書佐（示例職缺）',territoryId:'sample-county',holderId:null,vacancySince:0},{id:'office-quartermaster',title:'轉運吏（示例職缺）',territoryId:'sample-county',holderId:null,vacancySince:0}];
 const historicalPeople:HistoricalPerson[]=[{id:'sun-jian',name:'孫堅',alive:true,location:'長江中游（節點資料）',role:'歷史人物（非玩家部下）',source:'《三國志》卷四十六〈吳書一·孫破虜討逆傳〉；年級精度'}];
 const versionIndex=PHASE4_CONTENT_VERSIONS.indexOf(contentVersion as typeof PHASE4_CONTENT_VERSIONS[number]),correctionVersionIndex=PHASE4_CONTENT_VERSIONS.indexOf('phase4-scenario-106');
 const visibleContent=HISTORY_CONTENT.filter(content=>(!content.retired||versionIndex<correctionVersionIndex)&&contentVersionIncludes(contentVersion,content.introducedIn));
 const nodes=visibleContent.map(content=>({contentId:content.id,status:'pending' as NodeStatus,actualCause:[...content.causes],carrier:content.carrier,evidence:[]}));
 if(year>=190){examples[0].status='competing';examples[0].faction='鄰近郡府（示例競爭勢力）';}
 // Source-mentioned historical actors are tracked separately from the playable sample roster.
 void persons;
 const model:Phase4Model={version:1,contentVersion,day:0,year,month,dayOfMonth:1,nodes,causes:[...new Set(['dong-zhuo-central-control','regional-arms-resistance','campaign-risk','local-office-vacancy',...visibleContent.filter(content=>content.introducedIn).flatMap(content=>content.causes)])],historicalPersons:historicalPeople,playerLocation:'家宅・庭院',medicalSupplies:1,territories:[{id:'sample-county',name:'潁川東部路線・郡縣示例',control:'名義影響',owner:'漢廷名義',population:10000,grain:1000,support:50,policy:null,interests:{gentry:50,farmers:50,merchants:50},example:true},{id:'sample-market',name:'許縣至潁川驛路（示例）',control:'穩定治理',owner:'地方官府',population:2500,grain:300,support:55,policy:'互市與道路',interests:{gentry:45,farmers:50,merchants:60},example:true}],offices,candidates:examples,routes:[{id:'route-county-market',from:'潁川東部路線・郡縣示例',to:'許縣至潁川驛路（示例）',days:ENGINEERING.travelDaysPerRoute,terrain:'平原驛道',risk:5,example:true},{id:'route-market-pass',from:'許縣至潁川驛路（示例）',to:'汝南渡口（示例）',days:4,terrain:'平原與渡口',risk:15,example:true}],convoys:[],battle:null,treaties:[],authorizations:[],policiesLog:[],externalUpdates:year>=190?[`${examples[0].name}已受鄰近郡府延請（示例競爭勢力）。`]:[],unified:false,ending:'continuing',chosenEnding:undefined,eventLedger:[]};
 if(contentVersion!==PHASE4_LEGACY_CONTENT_VERSION){for(const node of model.nodes){const content=nodeContent(node.contentId);if(content.introducedIn&&year>=content.startYear)processHistoryNode(model,node);}}
